"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState, useRef, useEffect, useCallback, useId } from "react";
import { Button } from "@/components/ui/Button";
import { Menu, X, ChevronDown, Phone } from "lucide-react";
import { cn } from "@/lib/utils";
import { SITE, CTA_LINKS } from "@/lib/constants";
import { useFormModal } from "@/contexts/FormModalContext";
import type { NavItem } from "@/types";

interface NavProps {
  links: readonly NavItem[];
  cta?: { href: string; label: string };
  className?: string;
}

/** A disclosure, not a modal: normal Tab order remains available outside it. */
function useNavigationDisclosure(open: boolean, close: () => void) {
  const containerRef = useRef<HTMLDivElement>(null);
  const toggleRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      close();
      if (containerRef.current?.contains(document.activeElement)) {
        toggleRef.current?.focus();
      }
    };
    const onPointerDown = (event: PointerEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) close();
    };
    // Closing on breakpoint changes prevents a hidden panel reopening on resize.
    const desktop = window.matchMedia("(min-width: 1280px)");
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    desktop.addEventListener("change", close);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
      desktop.removeEventListener("change", close);
    };
  }, [open, close]);

  return { containerRef, toggleRef };
}

function DesktopDropdown({ item }: { item: NavItem }) {
  const [open, setOpen] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const close = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(false);
  }, []);
  const { containerRef, toggleRef } = useNavigationDisclosure(open, close);
  const panelId = useId();

  function handleEnter() {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(true);
  }

  function handleLeave() {
    timeoutRef.current = setTimeout(() => {
      if (!containerRef.current?.contains(document.activeElement)) close();
    }, 150);
  }

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="relative"
      onMouseEnter={handleEnter}
      onMouseLeave={handleLeave}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node)) close();
      }}
    >
      <button
        type="button"
        className="inline-flex items-center gap-1 text-sm font-medium text-foreground/70 transition-colors hover:text-primary"
        ref={toggleRef}
        aria-controls={panelId}
        aria-expanded={open}
        onClick={() => setOpen(!open)}
      >
        {item.label}
        <ChevronDown
          className={cn(
            "h-3.5 w-3.5 transition-transform duration-150",
            open && "rotate-180"
          )}
        />
      </button>

      <div
        id={panelId}
        className={cn(
          "absolute left-1/2 top-full z-50 -translate-x-1/2 pt-3 transition-all duration-150",
          open
            ? "pointer-events-auto translate-y-0 opacity-100"
            : "pointer-events-none -translate-y-1 opacity-0"
        )}
        inert={!open}
        onFocus={handleEnter}
        onBlur={(e) => {
          if (!containerRef.current?.contains(e.relatedTarget as Node)) {
            setOpen(false);
          }
        }}
      >
        <div className="w-56 overflow-hidden rounded-xl border border-border/60 bg-white p-2 shadow-lg">
          {item.children?.map((child) => (
            <Link
              key={child.href}
              href={child.href}
              className="block rounded-lg px-3.5 py-2.5 text-sm font-medium text-foreground/80 transition-colors hover:bg-primary/5 hover:text-primary"
              onClick={() => setOpen(false)}
            >
              {child.label}
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

export function Nav(props: NavProps) {
  const pathname = usePathname();
  // Route changes, including Back/Forward, reset all disclosures without stealing focus.
  return <Navigation key={pathname} {...props} pathname={pathname} />;
}

function Navigation({ links, cta, className, pathname }: NavProps & { pathname: string }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [mobileServicesOpen, setMobileServicesOpen] = useState(false);
  const { openModal } = useFormModal();
  const closeMobile = useCallback(() => {
    setMobileOpen(false);
    setMobileServicesOpen(false);
  }, []);
  const { containerRef, toggleRef: mobileToggleRef } = useNavigationDisclosure(mobileOpen, closeMobile);
  const mobilePanelId = useId();
  const mobileServicesId = useId();

  const isActive = (href: string) =>
    pathname === href || pathname.startsWith(href + "/");

  return (
    <div
      ref={containerRef}
      className={cn("flex items-center", className)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node)) closeMobile();
      }}
    >
      {/* Desktop nav */}
      <nav
        className="hidden items-center gap-8 xl:flex"
        aria-label="Main navigation"
      >
        {links.map((item) =>
          item.children ? (
            <DesktopDropdown key={item.href} item={item} />
          ) : (
            <Link
              key={item.href}
              href={item.href}
              className={cn(
                "text-sm font-medium transition-colors hover:text-primary",
                isActive(item.href)
                  ? "text-primary font-semibold"
                  : "text-foreground/70"
              )}
              aria-current={isActive(item.href) ? "page" : undefined}
            >
              {item.label}
            </Link>
          )
        )}
      </nav>

      {/* Desktop right side: phone + CTA */}
      <div className="ml-8 hidden items-center gap-4 xl:flex">
        {SITE.phone && (
          <a
            href={SITE.phoneHref}
            className="inline-flex items-center gap-1.5 text-sm font-medium text-foreground/70 transition-colors hover:text-primary"
          >
            <Phone className="h-4 w-4" />
            {SITE.phone}
          </a>
        )}
        {cta && (
          <Button 
            href={cta.label === CTA_LINKS.requestCare.label || cta.label === CTA_LINKS.makeReferral.label ? undefined : cta.href} 
            size="sm" 
            variant="secondary"
            onClick={
              cta.label === CTA_LINKS.requestCare.label 
                ? () => openModal("contact", "desktop_navigation")
                : cta.label === CTA_LINKS.makeReferral.label 
                ? () => openModal("referral", "desktop_navigation")
                : undefined
            }
          >
            {cta.label}
          </Button>
        )}
      </div>

      {/* Mobile toggle */}
      <button
        type="button"
        className="inline-flex h-10 w-10 items-center justify-center rounded-lg text-foreground/70 transition-colors hover:bg-muted xl:hidden"
        aria-expanded={mobileOpen}
        ref={mobileToggleRef}
        aria-controls={mobilePanelId}
        onClick={() => mobileOpen ? closeMobile() : setMobileOpen(true)}
      >
        <span className="sr-only">{mobileOpen ? "Close menu" : "Open menu"}</span>
        {mobileOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
      </button>

      {/* Mobile panel */}
      <div
        id={mobilePanelId}
        className={cn(
          "fixed inset-x-0 top-[64px] z-40 overflow-y-auto border-t border-border/40 bg-white transition-all duration-200 xl:hidden",
          mobileOpen
            ? "max-h-[calc(100vh-64px)] opacity-100"
            : "max-h-0 opacity-0 overflow-hidden"
        )}
        inert={!mobileOpen}
      >
        <div className="mx-auto max-w-[72rem] px-4 py-4 sm:px-6">
          <nav className="flex flex-col gap-1" aria-label="Mobile navigation">
            {links.map((item) =>
              item.children ? (
                <div key={item.href}>
                  <button
                    type="button"
                    className="flex w-full items-center justify-between rounded-lg px-3 py-3 text-base font-medium text-foreground transition-colors hover:bg-muted"
                    aria-controls={`${mobileServicesId}-${item.href}`}
                    aria-expanded={mobileServicesOpen}
                    onClick={() => setMobileServicesOpen(!mobileServicesOpen)}
                  >
                    {item.label}
                    <ChevronDown
                      className={cn(
                        "h-4 w-4 text-muted-foreground transition-transform duration-150",
                        mobileServicesOpen && "rotate-180"
                      )}
                    />
                  </button>
                  <div
                    id={`${mobileServicesId}-${item.href}`}
                    inert={!mobileServicesOpen}
                    className={cn(
                      "overflow-hidden transition-all duration-200",
                      mobileServicesOpen ? "max-h-96" : "max-h-0"
                    )}
                  >
                    <div className="ml-3 border-l-2 border-primary/10 pl-3">
                      {item.children.map((child) => (
                        <Link
                          key={child.href}
                          href={child.href}
                          className="block rounded-lg px-3 py-2.5 text-sm font-medium text-foreground/70 transition-colors hover:bg-muted hover:text-primary"
                          onClick={closeMobile}
                        >
                          {child.label}
                        </Link>
                      ))}
                    </div>
                  </div>
                </div>
              ) : (
                <Link
                  key={item.href}
                  href={item.href}
                  className="rounded-lg px-3 py-3 text-base font-medium text-foreground transition-colors hover:bg-muted"
                  onClick={closeMobile}
                >
                  {item.label}
                </Link>
              )
            )}
          </nav>

          <div className="mt-4 border-t border-border/40 pt-4">
            {SITE.phone && (
              <a
                href={SITE.phoneHref}
                className="mb-3 flex items-center gap-2 rounded-lg px-3 py-2.5 text-base font-medium text-foreground transition-colors hover:bg-muted"
                onClick={closeMobile}
              >
                <Phone className="h-5 w-5 text-primary" />
                {SITE.phone}
              </a>
            )}
            {cta && (
              <Button
                href={cta.label === CTA_LINKS.requestCare.label || cta.label === CTA_LINKS.makeReferral.label ? undefined : cta.href}
                size="md"
                className="w-full"
                onClick={() => {
                  closeMobile();
                  if (cta.label === CTA_LINKS.requestCare.label) openModal("contact", "mobile_navigation", mobileToggleRef.current);
                  else if (cta.label === CTA_LINKS.makeReferral.label) openModal("referral", "mobile_navigation", mobileToggleRef.current);
                }}
              >
                {cta.label}
              </Button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

